/** A request the server refused. The message is the UI's words for its code (language/errors.ts), never the server's sentence. */
export class ApiError extends Error {
  /** The error's code, where the answer is the server's. */
  readonly code: Code | null;
  /** What the server's answer gives with its code (the seconds of a wait, ...). */
  readonly details: NonNullable<Answered>["details"];
  constructor(
    readonly status: number,
    body: Answered | Code,
  ) {
    const answered = typeof body === "string" ? { code: body } : body;
    super(errorWords(status, answered));
    this.code = answered?.code ?? null;
    this.details = answered?.details ?? {};
  }
}

/** Whether a request failed because it needs a model and the user has no provider yet: the server's 424. */
export const needsSetup = (error: unknown) => error instanceof ApiError && error.status === 424;

/** The page's mark, by which the server knows a change it made. Made of chance, as `crypto.randomUUID` is not there for a page of the home network, which is not a secure context. */
const PAGE = Array.from({ length: 4 }, () => Math.random().toString(36).slice(2, 10)).join("");

/** Whether a request was refused as the server waits for the password: its 423. */
export const isLocked = (error: unknown) => error instanceof ApiError && error.status === 423;

/** The header of a 401 that says the page is to sign in (`SIGN_IN` in server/src/api.rs). */
const SIGN_IN = "x-cardwave-sign-in";

/** Whether the page is starting anew. */
let leaving = false;

/** Whether the page has started as an account's: before, it may be asked to sign in, and is shown the sign-in screen anyway. */
let started = false;
export const startedSignedIn = () => void (started = true);

/** The page is to sign in: one that has started starts anew, once, and main.ts asks it to. */
function signedOut(): void {
  if (leaving || !started) return;
  leaving = true;
  location.reload();
}

/** Sends `body` as JSON, or as it is when it is a file. Returns the answer, unless the server refused. `signal` hangs up; `more` is headers of the request's own. */
async function send(method: string, path: string, body?: unknown, signal?: AbortSignal, more: Record<string, string> = {}, keepalive = false): Promise<Response> {
  const headers: Record<string, string> = { "X-Cardwave-Page": PAGE, ...more };
  const init: RequestInit = { method, headers, signal, keepalive };
  if (body instanceof Blob) {
    init.body = body;
  } else if (body !== undefined) {
    init.body = JSON.stringify(body);
    headers["Content-Type"] = "application/json";
  }
  const res = await fetch(path, init);
  if (res.status === 401 && res.headers.has(SIGN_IN)) signedOut();
  if (!res.ok) {
    // An answer that is not the server's JSON (a proxy's) is worded by its status.
    throw new ApiError(res.status, await res.json().catch(() => null));
  }
  return res;
}

/** [`send`] for an answer that is JSON, or nothing. */
async function request<T>(method: string, path: string, body?: unknown, signal?: AbortSignal): Promise<T> {
  const res = await send(method, path, body, signal);
  return res.status === 204 ? (undefined as T) : res.json();
}

/** The store of the provider that is on its way, on whichever screen it was started: done when it has been answered. */
let storing: Promise<unknown> = Promise.resolve();

/**
 * The user's provider, or `null` when none is set up yet: as it is stored after a store on its way, so that a
 * screen opened while another's store is still going shows what that one stored, and stores nothing older over it.
 * A screen stores only when it has read, so no two stores are on their way at once.
 */
export const getProvider = () => storing.then(() => request<ProviderView | null>("GET", "/api/provider"));

/** The word a copy's name ends in, in the page's language, which the server puts in the copy's name ("Rig (copy)"). */
const copied = (): Copied => ({ copy: wording("common-copy-word") });

/** Counts `sent` as the store of the provider that is on its way, until it is answered either way. */
function store<T>(sent: Promise<T>): Promise<T> {
  storing = sent.catch(() => {});
  return sent;
}

export const setProvider = (provider: SetProvider) => store(request<ProviderView>("PUT", "/api/provider", provider));

