/** `path` with what `query` asks for behind it; what is empty is left out, and a list is asked for item by item. */
function withQuery(path: string, query: object): string {
  const asked = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    for (const one of [value].flat()) if (one) asked.append(key, one);
  }
  return asked.size ? `${path}?${asked}` : path;
}

