/** The longest text sent as the page closes in a request that outlives it (at most 64 KB, three bytes a sign). */
const KEEPALIVE_TEXT = 16_000;

/** A field's unsaved text (../unsaved.ts), or null where none is kept. */
export const getUnsaved = (field: string) => request<Unsaved | null>("GET", `/api/unsaved/${encodeURIComponent(field)}`);
/** Keeps a field's unsaved text, an empty one forgetting it; with `closing`, also while the page closes. */
export const keepUnsaved = async (field: string, text: string, closing = false) => {
  // A request that outlives the page carries at most 64 KB, so a longer text goes as any other request.
  await send("PUT", `/api/unsaved/${encodeURIComponent(field)}`, { text } satisfies Unsaved, undefined, {}, closing && text.length <= KEEPALIVE_TEXT);
};
/** Imports a card file (CCV4 or SillyTavern PNG) as a new card, which keeps the file's name for its texts' imported drafts. */
export const importCard = (file: File) => request<Imported>("POST", `/api/cards?name=${encodeURIComponent(file.name)}`, file);

/** A file's bytes in base64. */
const base64 = (file: Blob) =>
  new Promise<string>((done, failed) => {
    const reader = new FileReader();
    reader.onload = () => done(String(reader.result).split(",")[1] ?? "");
    reader.onerror = () => failed(reader.error);
    reader.readAsDataURL(file);
  });

