/** A file to save, under the name the server gives it. */
export type Download = { name: string; file: Blob };

/** Asks for a file to save; it is called `unnamed` when the server names none. */
async function download(path: string, unnamed: string): Promise<Download> {
  const res = await send("GET", path);
  const named = /filename\*=UTF-8''([^;]+)/.exec(res.headers.get("Content-Disposition") ?? "");
  return { name: named ? decodeURIComponent(named[1]) : unnamed, file: await res.blob() };
}

