/**
 * Has the browser save all the server holds, with its key sealed by `password` (where no password is on; else by
 * the one that is), as it comes, never held in the page: a form's post into a hidden frame, so the page stays. A
 * file saved loads nothing into the frame; what the server refuses does, and is given to `failed`.
 */
export function saveBackup(password: string | undefined, failed: (reason: string) => void): void {
  const frame = document.querySelector<HTMLIFrameElement>("iframe[name=backup]") ?? document.body.appendChild(Object.assign(document.createElement("iframe"), { name: "backup", hidden: true }));
  frame.onload = () => {
    // The frame's first, empty page loads late in some browsers (Firefox).
    const page = frame.contentDocument;
    if (!page || page.URL === "about:blank") return;
    let answered: Answered = null;
    try {
      answered = JSON.parse(page.body.textContent ?? "");
    } catch {
      // Not the server's JSON: the backup failed, with no more said.
    }
    failed(answered?.code ? errorWords(400, answered) : wording("client-backup-failed"));
  };
  const form = Object.assign(document.createElement("form"), { method: "post", action: "/api/backup/save", target: "backup", hidden: true });
  if (password !== undefined) form.append(Object.assign(document.createElement("input"), { type: "hidden", name: "password", value: password }));
  document.body.append(form);
  form.submit();
  form.remove();
}
/** Puts what the backup `file` holds in the place of all the server holds; `password` is the one it was made with, where it needs one (else 401). */
export const restoreBackup = async (file: Blob, password?: string) => {
  // Percent-encoded, as a header holds ASCII alone.
  await send("POST", "/api/backup", file, undefined, password === undefined ? {} : { "X-Cardwave-Password": encodeURIComponent(password) });
};
export const changeSettings = (change: ChangeSettings) => request<Settings>("PATCH", "/api/settings", change);
/** The page's change of the companion on its way, so that the next reads what this one stored. */
let companionChange: Promise<unknown> = Promise.resolve();
/**
 * Changes `patch` of the companion's settings, kept whole on the server, onto the companion as read just before,
 * so that nothing else of it is undone; the page's changes go one after another. Answers the settings then.
 */
export function changeCompanion(patch: Partial<Companion>): Promise<Settings> {
  const sent = companionChange.then(async () => {
    const { companion } = await getSettings();
    return changeSettings({ companion: { ...companion, ...patch } });
  });
  companionChange = sent.catch(() => {});
  return sent;
}
