/** A file that comes with the UI: its text, empty where there is none (a missing one is answered with index.html). */
const shipped = (path: string) =>
  fetch(path).then((answer) => (answer.ok && !answer.headers.get("content-type")?.includes("text/html") ? answer.text() : ""));

