export const moveCharacter = (characterId: number, to: MoveCharacter) => request<ChatView>("PUT", `/api/chat-characters/${characterId}/position`, to);
/** Takes a character that has written nothing out of its chat again. Returns the chat. */
export const removeCharacter = (characterId: number) => request<ChatView>("DELETE", `/api/chat-characters/${characterId}`);

/** The user's personas in plain view, by name, or those `query` asks for. */
export const listPersonas = (query: PersonaQuery = {}) => request<Persona[]>("GET", withQuery("/api/personas", query));
export const createPersona = (persona: NewPersona) => request<Persona>("POST", "/api/personas", persona);
/** Gives a persona the picture `file`, or takes its picture away (`null`). */
export const setPersonaPicture = (id: number, file: Blob | null) =>
  file ? request<Persona>("PUT", `/api/personas/${id}/picture`, file) : request<Persona>("DELETE", `/api/personas/${id}/picture`);
/** Changes a persona's name, description, order or lorebooks, makes it the default, or trashes it or takes that back. */
export const changePersona = (id: number, change: ChangePersona) => request<Persona>("PATCH", `/api/personas/${id}`, change);
/** Makes the user this persona in the chat from the next reply on; `null` takes the persona off. */
export const setPersona = (chatId: number, personaId: number | null) =>
  personaId === null
    ? request<Chat>("DELETE", `/api/chats/${chatId}/persona`)
    : request<Chat>("PUT", `/api/chats/${chatId}/persona`, { persona_id: personaId });
/** Leaves a lorebook or one of its entries out of the chat's prompts, or takes it back in. Returns the chat's lorebooks. */
export const setLore = (chatId: number, lore: SetLore) => request<ChatLorebook[]>("PUT", `/api/chats/${chatId}/lore`, lore);
/** Takes a lorebook of the library along in the chat, from the next reply on. Returns the chat's lorebooks. */
export const addLorebook = (chatId: number, lorebook: AddLorebook) =>
  request<ChatLorebook[]>("POST", `/api/chats/${chatId}/lorebooks`, lorebook);
/** Lets a lorebook of the library go from the chat. Returns the chat's lorebooks. */
export const removeLorebook = (chatId: number, lorebookId: number) =>
  request<ChatLorebook[]>("DELETE", `/api/chats/${chatId}/lorebooks/${lorebookId}`);

/** The library's lorebooks in plain view, by name, or those `query` asks for. */
export const listLorebooks = (query: LorebookQuery = {}) => request<Lorebook[]>("GET", withQuery("/api/lorebooks", query));
/** The library's own lorebooks in plain view, without the cards' own that its list shows too: those a chat or a card takes along. */
export const libraryLorebooks = async () => (await listLorebooks()).filter((lorebook) => !lorebook.card);
/** A card's lorebooks: those it brings, then those of the library attached to it. */
export const cardLorebooks = (cardId: number) => request<CardLorebook[]>("GET", `/api/cards/${cardId}/lorebooks`);
/** Attaches a lorebook of the library to a card, for all its chats. Returns the card's lorebooks. */
export const attachLorebook = (cardId: number, lorebook: AddLorebook) =>
  request<CardLorebook[]>("POST", `/api/cards/${cardId}/lorebooks`, lorebook);
/** Detaches a lorebook of the library from a card. Returns the card's lorebooks. */
export const detachLorebook = (cardId: number, lorebookId: number) =>
  request<CardLorebook[]>("DELETE", `/api/cards/${cardId}/lorebooks/${lorebookId}`);
/** Copies a lorebook a card brings into the library. Returns the new lorebook. */
export const copyLorebook = (cardId: number, which: Reference) =>
  request<Lorebook>("POST", `/api/cards/${cardId}/lorebooks/copy`, { ...which, ...copied() } satisfies CopiedReference);
/** Imports a lorebook file (SillyTavern world info, or a card's lorebook saved by itself) as a new lorebook. */
export const importLorebook = (file: File) =>
  request<ImportedLorebook>("POST", withQuery("/api/lorebooks", { name: file.name }), file);
/** Makes a lorebook without entries, under a name and a description. */
export const createLorebook = (lorebook: NewLorebook) => request<Lorebook>("POST", "/api/lorebooks/new", lorebook);
/** Stars, archives or trashes a lorebook, or takes that back, or gives it another name or description. */
export const changeLorebook = (id: number, change: ChangeLorebook) => request<Lorebook>("PATCH", `/api/lorebooks/${id}`, change);
/** What Search Cardwave finds of `q`: by its words, and with `meaning` by its meaning after them where the search model answers. */
export const findAll = (q: string, meaning: boolean, signal?: AbortSignal) => request<Hit[]>("GET", withQuery("/api/find", { q, meaning: meaning ? "true" : "" }), undefined, signal);
/** What the characters of the user's chats remember, as each memory holds now, the newest first (Knowledge › Memories). */
export const listMemories = () => request<MemoryView[]>("GET", "/api/memories");
/** Changes a memory's text, or who of its chat's characters and the user know it. Returns the memory. */
export const changeMemory = (id: string, change: ChangeMemory) => request<MemoryView>("PATCH", `/api/memories/${id}`, change);
/** Deletes a memory, which `restoreMemory` puts back until the server starts again. */
export const deleteMemory = (id: string) => request<void>("DELETE", `/api/memories/${id}`);
export const restoreMemory = (id: string) => request<MemoryView>("POST", `/api/memories/${id}/restore`);
/** The documents of the user's chats and cards, those in the Trash aside, the newest first (Knowledge › Documents). */
export const listDocuments = () => request<DocumentView[]>("GET", "/api/documents");
/** Gives a chat a document: a .txt, .md, .pdf or .docx file. */
export const addChatDocument = (chatId: number, file: File) =>
  request<DocumentView>("POST", withQuery(`/api/chats/${chatId}/documents`, { name: file.name }), file);
/** Gives a card a document, for every reply its character writes. */
export const addCardDocument = (cardId: number, file: File) =>
  request<DocumentView>("POST", withQuery(`/api/cards/${cardId}/documents`, { name: file.name }), file);
/** Deletes a document, which `restoreDocument` puts back until the server starts again. */
export const deleteDocument = (id: number) => request<void>("DELETE", `/api/documents/${id}`);
export const restoreDocument = (id: number) => request<DocumentView>("POST", `/api/documents/${id}/restore`);
/** Which lorebook an editor is of: one of the library, or one a card brings itself (`book`, its reference, where it is not the card's first). */
export type LoreOf = { library: number } | { card: number; book?: string };
/** Where the editor of the lorebook `of` asks, with `path` and `query` behind it. */
const lorePath = (of: LoreOf, path: string, query: object = {}) =>
  "library" in of ? withQuery(`/api/lorebooks/${of.library}${path}`, query) : withQuery(`/api/cards/${of.card}/lorebook${path}`, { book: of.book, ...query });
/** A lorebook as its editor shows it: its name, its description and its entries. */
export const getLorebookEdit = (of: LoreOf) => request<LorebookEdit>("GET", lorePath(of, "/edit"));
/** Gives a lorebook another name, description, scan depth or token budget ("Lorebook settings"). */
export const describeLorebook = (of: LoreOf, change: ChangeLorebook) => request<unknown>("PATCH", lorePath(of, ""), change);
/** Where an entry of a lorebook is asked for: its reference is one part of the address. */
const entryPath = (of: LoreOf, reference: string, rest = "", query: object = {}) => lorePath(of, `/entries/${encodeURIComponent(reference)}${rest}`, query);
/** Adds an entry to a lorebook, as its last. Returns the entry. */
export const addEntry = (of: LoreOf, entry: EntryChange) => request<EditEntry>("POST", lorePath(of, "/entries"), entry);
/** Changes what `change` names of a lorebook's entry; new words are a version made by `made` ("edited" where none is said). Returns the entry as it then is. */
export const changeEntry = (of: LoreOf, reference: string, change: EntryChange, made?: string) =>
  request<EditEntry>("PATCH", entryPath(of, reference, "", { made }), change);
/** Takes an entry out of a lorebook. Returns what puts it back. */
export const removeEntry = (of: LoreOf, reference: string) => request<RemovedEntry>("DELETE", entryPath(of, reference));
/** Puts an entry that was taken out back where it stood. Returns the entry. */
export const restoreEntry = (of: LoreOf, removed: RemovedEntry) => request<EditEntry>("POST", lorePath(of, "/entries/restore"), removed);
/** The versions of an entry's words, the newest first. */
export const entryDrafts = (of: LoreOf, reference: string) => request<TextDrafts>("GET", entryPath(of, reference, "/drafts"));
/** Moves a lorebook a card brings into the library, which the card then uses ("Move to library"). Returns it as the library lists it. */
export const moveLorebook = (cardId: number, which: Reference) => request<Lorebook>("POST", `/api/cards/${cardId}/lorebook/move`, which);
/** Puts a lorebook moved into the library back into the card (the Undo of "Move to library"). */
export const moveBack = (cardId: number, lorebookId: number) => request<void>("POST", `/api/cards/${cardId}/lorebooks/${lorebookId}/back`);
/** Has the background model change a lorebook's entries by one of the lorebook's AI tools; nothing stored. `signal` stops it. */
export const rewriteLore = (asked: LoreRewrite, signal?: AbortSignal) => request<LoreText[]>("POST", "/api/rewrite/lore", asked, signal);

/** Starts a reply. The answer is the new message, still empty; its text follows as events. */
export const generate = (chatId: number, how: Generate) =>
  request<MessageView>("POST", `/api/chats/${chatId}/generate`, how);
export const stopReply = (chatId: number) => request<void>("POST", `/api/chats/${chatId}/stop`);
/** Answers the call of a tool that waits in the chat: whether it may run. */
/** Answers a tool's call that waits; `forChat`, with `allow`, lets such calls of the chat run from now on without asking. */
export const answerTool = (chatId: number, allow: boolean, forChat = false) => request<void>("POST", `/api/chats/${chatId}/answer`, { allow, for_chat: forChat });
/** The tools the model wrote for the account (code mode), the newest first. */
export const listWrittenTools = () => request<WrittenTool[]>("GET", "/api/tools/written");
/** Switches a tool the model wrote on or off. */
export const switchWrittenTool = (id: number, on: boolean) => request<WrittenTool>("PATCH", `/api/tools/written/${id}`, { on });
/** Deletes a tool the model wrote, which `restoreWrittenTool` puts back until the server starts again. */
export const deleteWrittenTool = (id: number) => request<void>("DELETE", `/api/tools/written/${id}`);
export const restoreWrittenTool = (id: number) => request<WrittenTool>("POST", `/api/tools/written/${id}/restore`);
/** Starts a coding task in the chat; its card follows as the chat's newest message. */
export const startTask = (chatId: number, task: StartTask) => request<Task>("POST", `/api/chats/${chatId}/tasks`, task);
/** The newest five coding tasks. */
export const recentTasks = () => request<TaskLine[]>("GET", "/api/coding/tasks");
export const getTask = (id: number) => request<Task>("GET", `/api/coding/tasks/${id}`);
export const stopTask = (id: number) => request<void>("POST", `/api/coding/tasks/${id}/stop`, {});
export const answerTask = (id: number, allow: boolean) => request<void>("POST", `/api/coding/tasks/${id}/answer`, { allow });
/** Puts a task's folder back to before the step `stepId`, or to before its first checkpoint. */
export const undoTask = (id: number, stepId?: number) => request<Task>("POST", `/api/coding/tasks/${id}/undo`, stepId === undefined ? {} : { step_id: stepId });
/** Has the model write the user's next message, or better the one given; answers with the text, once all of it is written. `signal` stops it. */
export const draft = (chatId: number, how: Draft, signal?: AbortSignal) => request<Drafted>("POST", `/api/chats/${chatId}/draft`, how, signal);

/** The account's image model, or `null` while none is set up. */
export const getImages = () => request<ImageModelView | null>("GET", "/api/images");
/** The image models an address lists, asked with the key that would go there; a ComfyUI's checkpoints too. */
export const listImageModels = (asked: ListModels) => request<ListedModels>("POST", "/api/images/models", asked);
/** Has a picture made for the chat, which may take minutes; answers with its message once it is there. `signal` stops it. */
export const makePicture = (chatId: number, how: MakePicture, signal?: AbortSignal) =>
  request<MessageView>("POST", `/api/chats/${chatId}/picture`, how, signal);
/** Where a message's picture is. */
export const pictureUrl = (messageId: number) => `/api/messages/${messageId}/picture`;
/** Makes a message's picture anew of `words`, as another version of it ("Make again"). `signal` stops it. */
export const makeAgain = (messageId: number, again: MakeAgain, signal?: AbortSignal) =>
  request<MessageView>("POST", pictureUrl(messageId), again, signal);

/**
 * Opens the event socket and reconnects after a second when it drops, or where
 * the app was locked starts the page anew. Each
 * connection starts with a `hello`; the server tells all that happens after it,
 * but for a change this page made.
 */
export function connectEvents(onEvent: (event: ServerEvent) => void): void {
  const url = `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}/ws?page=${PAGE}`;
  const ws = new WebSocket(url);
  ws.onmessage = (msg) => onEvent(JSON.parse(msg.data));
  const again = () => setTimeout(() => connectEvents(onEvent), 1000);
  ws.onclose = () => void getLock().then((lock) => (lock.locked ? location.reload() : again()), again);
}
